CREATE TABLE rt_hotels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name_en varchar(255) NOT NULL, name_ar varchar(255), country_code char(2), city_name varchar(180), latitude numeric(10,7), longitude numeric(10,7), status varchar(24) NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rt_supplier_hotels (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES rt_suppliers(id) ON DELETE RESTRICT, hotel_id uuid NOT NULL REFERENCES rt_hotels(id) ON DELETE RESTRICT, external_hotel_id varchar(255) NOT NULL, mapping_status varchar(24) NOT NULL DEFAULT 'pending', UNIQUE(supplier_id,external_hotel_id));
CREATE INDEX rt_supplier_hotels_hotel_idx ON rt_supplier_hotels(hotel_id);
CREATE TABLE rt_transport_providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid REFERENCES rt_suppliers(id) ON DELETE RESTRICT, company_name varchar(255) NOT NULL, status varchar(24) NOT NULL DEFAULT 'pending');
CREATE TABLE rt_vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES rt_transport_providers(id) ON DELETE RESTRICT, vehicle_class varchar(64) NOT NULL, plate_number varchar(80), seats integer NOT NULL CHECK(seats>0), status varchar(24) NOT NULL DEFAULT 'active');
CREATE TABLE rt_drivers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider_id uuid NOT NULL REFERENCES rt_transport_providers(id) ON DELETE RESTRICT, full_name varchar(255) NOT NULL, phone varchar(40), status varchar(24) NOT NULL DEFAULT 'active');
